Here is a typical example of using the send and receive functions:
#include “ mpi.h ”
#include <iostream>
int main( int argc, char *argv[])
{
int rank, buffer;
MPI::Init(argv, argc);
rank = MPI::COMM_WORLD.Get_rank();
// Process 0 sends data as buffer and Process 1 receives data as buffer
if (rank == 0) {
buffer = 999999;
MPI::COMM_WORLD.Send( &buffer, 1, MPI::INT, 1, 0 );
}
else if (rank == 1) {
MPI::COMM_WORLD.Recv( &buffer, 1, MPI::INT, 0, 0 );
std::cout << “ Data Received “ << buf << “ \n ”;
}
MPI::Finalize();
return 0;
}
When running via MPI, the communicator will send data that will be received by the
receive function in another processor.
